  5239  /* Eat from start of current (textual) block any reference definitions and
  5240   * remember them so we can resolve any links referring to them.
  5241   *
  5242   * (Reference definitions can only be at start of it as they cannot break
  5243   * a paragraph.)
  5244   */
  5245  static int
  5246  md_consume_link_reference_definitions(MD_CTX* ctx)
  5247  {
  5248      MD_LINE* lines = (MD_LINE*) (ctx->current_block + 1);
  5249      MD_SIZE n_lines = ctx->current_block->n_lines;
  5250      MD_SIZE n = 0;
  5980  md_line_indentation(MD_CTX* ctx, unsigned total_indent, OFF beg, OFF* p_end)
  5981  {
  5982      OFF off = beg;
  5983      unsigned indent = total_indent;
  5984
  5985      while(off < ctx->size  &&  ISBLANK(off)) {
  5986          if(CH(off) == _T('\t'))
  5987              indent = (indent + 4) & ~3;
  5988          else
  5989              indent++;
  5990          off++;
  5991      }
  5992
  5993      *p_end = off;
  5994      return indent - total_indent;
  5995  }
  5996
  5997  static const MD_LINE_ANALYSIS md_dummy_blank_line = { MD_LINE_BLANK, 0, 0, 0, 0, 0 };
  5998
  5999  /* Analyze type of the line and find some its properties. This serves as a
  6000   * main input for determining type and boundaries of a block. */
  6001  static int
  6002  md_analyze_line(MD_CTX* ctx, OFF beg, OFF* p_end,
  6003                  const MD_LINE_ANALYSIS* pivot_line, MD_LINE_ANALYSIS* line)
  6004  {
  6005      unsigned total_indent = 0;
  6006      int n_parents = 0;
  6007      int n_brothers = 0;
  6008      int n_children = 0;
  6009      MD_CONTAINER container = { 0 };
  6010      int prev_line_has_list_loosening_effect = ctx->last_line_has_list_loosening_effect;
  6011      OFF off = beg;
  6012      OFF hr_killer = 0;
  6013      int ret = 0;
  6014
  6015      line->indent = md_line_indentation(ctx, total_indent, off, &off);
  6016      total_indent += line->indent;
  6017      line->beg = off;
  6018      line->enforce_new_block = FALSE;
  6019
  6020      /* Given the indentation and block quote marks '>', determine how many of
  6021       * the current containers are our parents. */
  6022      while(n_parents < ctx->n_containers) {
  6023          MD_CONTAINER* c = &ctx->containers[n_parents];
  6024
  6025          if(c->ch == _T('>')  &&  line->indent < ctx->code_indent_offset  &&
  6026              off < ctx->size  &&  CH(off) == _T('>'))
  6027          {
  6028              /* Block quote mark. */
  6029              off++;
  6030              total_indent++;
  6031              line->indent = md_line_indentation(ctx, total_indent, off, &off);
  6032              total_indent += line->indent;
  6033
  6034              /* The optional 1st space after '>' is part of the block quote mark. */
  6035              if(line->indent > 0)
  6036                  line->indent--;
  6037
  6038              line->beg = off;
  6039
  6040          } else if(c->ch != _T('>')  &&  line->indent >= c->contents_indent) {
  6041              /* List. */
  6042              line->indent -= c->contents_indent;
  6043          } else {
  6044              break;
  6045          }
  6046
  6047          n_parents++;
  6048      }
  6049
  6050      if(off >= ctx->size  ||  ISNEWLINE(off)) {
  6051          /* Blank line does not need any real indentation to be nested inside
  6052           * a list. */
  6053          if(n_brothers + n_children == 0) {
  6054              while(n_parents < ctx->n_containers  &&  ctx->containers[n_parents].ch != _T('>'))
  6055                  n_parents++;
  6056          }
  6057      }
  6058
  6059      while(TRUE) {
  6060          /* Check whether we are fenced code continuation. */
  6061          if(pivot_line->type == MD_LINE_FENCEDCODE) {
  6062              line->beg = off;
  6063
  6064              /* We are another MD_LINE_FENCEDCODE unless we are closing fence
  6065               * which we transform into MD_LINE_BLANK. */
  6066              if(line->indent < ctx->code_indent_offset) {
  6067                  if(md_is_closing_code_fence(ctx, CH(pivot_line->beg), off, &off)) {
  6068                      line->type = MD_LINE_BLANK;
  6069                      ctx->last_line_has_list_loosening_effect = FALSE;
  6070                      break;
  6071                  }
  6072              }
  6073
  6074              /* Change indentation accordingly to the initial code fence. */
  6075              if(n_parents == ctx->n_containers) {
  6076                  if(line->indent > pivot_line->indent)
  6077                      line->indent -= pivot_line->indent;
  6078                  else
  6079                      line->indent = 0;
  6080
  6081                  line->type = MD_LINE_FENCEDCODE;
  6082                  break;
  6083              }
  6084          }
  6085
  6086          /* Check whether we are HTML block continuation. */
  6087          if(pivot_line->type == MD_LINE_HTML  &&  ctx->html_block_type > 0) {
  6088              if(n_parents < ctx->n_containers) {
  6089                  /* HTML block is implicitly ended if the enclosing container
  6090                   * block ends. */
  6091                  ctx->html_block_type = 0;
  6092              } else {
  6093                  int html_block_type;
  6094
  6095                  html_block_type = md_is_html_block_end_condition(ctx, off, &off);
  6096                  if(html_block_type > 0) {
  6097                      MD_ASSERT(html_block_type == ctx->html_block_type);
  6098
  6099                      /* Make sure this is the last line of the block. */
  6100                      ctx->html_block_type = 0;
  6101
  6102                      /* Some end conditions serve as blank lines at the same time. */
  6103                      if(html_block_type == 6 || html_block_type == 7) {
  6104                          line->type = MD_LINE_BLANK;
  6105                          line->indent = 0;
  6106                          break;
  6107                      }
  6108                  }
  6109
  6110                  line->type = MD_LINE_HTML;
  6111                  n_parents = ctx->n_containers;
  6112                  break;
  6113              }
  6114          }
  6115
  6116          /* Check for blank line. */
  6117          if(off >= ctx->size  ||  ISNEWLINE(off)) {
  6118              if(pivot_line->type == MD_LINE_INDENTEDCODE  &&  n_parents == ctx->n_containers) {
  6119                  line->type = MD_LINE_INDENTEDCODE;
  6120                  if(line->indent > ctx->code_indent_offset)
  6121                      line->indent -= ctx->code_indent_offset;
  6122                  else
  6123                      line->indent = 0;
  6124                  ctx->last_line_has_list_loosening_effect = FALSE;
  6125              } else {
  6126                  line->type = MD_LINE_BLANK;
  6127                  ctx->last_line_has_list_loosening_effect = (n_parents > 0  &&
  6128                          n_brothers + n_children == 0  &&
  6129                          ctx->containers[n_parents-1].ch != _T('>'));
  6130
  6131      #if 1
  6132                  /* See https://github.com/mity/md4c/issues/6
  6133                   *
  6134                   * This ugly checking tests we are in (yet empty) list item but
  6135                   * not its very first line (i.e. not the line with the list
  6136                   * item mark).
  6137                   *
  6138                   * If we are such a blank line, then any following non-blank
  6139                   * line which would be part of the list item actually has to
  6140                   * end the list because according to the specification, "a list
  6141                   * item can begin with at most one blank line."
  6142                   */
  6143                  if(n_parents > 0  &&  ctx->containers[n_parents-1].ch != _T('>')  &&
  6144                     n_brothers + n_children == 0  &&  ctx->current_block == NULL  &&
  6145                     ctx->n_block_bytes > (int) sizeof(MD_BLOCK))
  6146                  {
  6147                      MD_BLOCK* top_block = (MD_BLOCK*) ((char*)ctx->block_bytes + ctx->n_block_bytes - sizeof(MD_BLOCK));
  6148                      if(top_block->type == MD_BLOCK_LI)
  6149                          ctx->last_list_item_starts_with_two_blank_lines = TRUE;
  6150                  }
  6151      #endif
  6152              }
  6153              break;
  6154          } else {
  6155      #if 1
  6156              /* This is the 2nd half of the hack. If the flag is set (i.e. there
  6157               * was a 2nd blank line at the beginning of the list item) and if
  6158               * we would otherwise still belong to the list item, we enforce
  6159               * the end of the list. */
  6160              if(ctx->last_list_item_starts_with_two_blank_lines) {
  6161                  if(n_parents > 0  &&  n_parents == ctx->n_containers  &&
  6162                     ctx->containers[n_parents-1].ch != _T('>')  &&
  6163                     n_brothers + n_children == 0  &&  ctx->current_block == NULL  &&
  6164                     ctx->n_block_bytes > (int) sizeof(MD_BLOCK))
  6165                  {
  6166                      MD_BLOCK* top_block = (MD_BLOCK*) ((char*)ctx->block_bytes + ctx->n_block_bytes - sizeof(MD_BLOCK));
  6167                      if(top_block->type == MD_BLOCK_LI) {
  6168                          n_parents--;
  6169
  6170                          line->indent = total_indent;
  6171                          if(n_parents > 0)
  6172                              line->indent -= MIN(line->indent, ctx->containers[n_parents-1].contents_indent);
  6173                      }
  6174                  }
  6175
  6176                  ctx->last_list_item_starts_with_two_blank_lines = FALSE;
  6177              }
  6178      #endif
  6179              ctx->last_line_has_list_loosening_effect = FALSE;
  6180          }
  6181
  6182          /* Check whether we are Setext underline. */
  6183          if(line->indent < ctx->code_indent_offset  &&  pivot_line->type == MD_LINE_TEXT
  6184              &&  off < ctx->size  &&  ISANYOF2(off, _T('='), _T('-'))
  6185              &&  (n_parents == ctx->n_containers))
  6186          {
  6187              unsigned level;
  6188
  6189              if(md_is_setext_underline(ctx, off, &off, &level)) {
  6190                  line->type = MD_LINE_SETEXTUNDERLINE;
  6191                  line->data = level;
  6192                  break;
  6193              }
  6194          }
  6195
  6196          /* Check for thematic break line. */
  6197          if(line->indent < ctx->code_indent_offset
  6198              &&  off < ctx->size  &&  off >= hr_killer
  6199              &&  ISANYOF(off, _T("-_*")))
  6200          {
  6201              if(md_is_hr_line(ctx, off, &off, &hr_killer)) {
  6202                  line->type = MD_LINE_HR;
  6203                  break;
  6204              }
  6205          }
  6206
  6207          /* Check for "brother" container. I.e. whether we are another list item
  6208           * in already started list. */
  6209          if(n_parents < ctx->n_containers  &&  n_brothers + n_children == 0) {
  6210              OFF tmp;
  6211
  6212              if(md_is_container_mark(ctx, line->indent, off, &tmp, &container)  &&
  6213                 md_is_container_compatible(&ctx->containers[n_parents], &container))
  6214              {
  6215                  pivot_line = &md_dummy_blank_line;
  6216
  6217                  off = tmp;
  6218
  6219                  total_indent += container.contents_indent - container.mark_indent;
  6220                  line->indent = md_line_indentation(ctx, total_indent, off, &off);
  6221                  total_indent += line->indent;
  6222                  line->beg = off;
  6223
  6224                  /* Some of the following whitespace actually still belongs to the mark. */
  6225                  if(off >= ctx->size || ISNEWLINE(off)) {
  6226                      container.contents_indent++;
  6227                  } else if(line->indent <= ctx->code_indent_offset) {
  6228                      container.contents_indent += line->indent;
  6229                      line->indent = 0;
  6230                  } else {
  6231                      container.contents_indent += 1;
  6232                      line->indent--;
  6233                  }
  6234
  6235                  ctx->containers[n_parents].mark_indent = container.mark_indent;
  6236                  ctx->containers[n_parents].contents_indent = container.contents_indent;
  6237
  6238                  n_brothers++;
  6239                  continue;
  6240              }
  6241          }
  6242
  6243          /* Check for indented code.
  6244           * Note indented code block cannot interrupt a paragraph. */
  6245          if(line->indent >= ctx->code_indent_offset  &&  (pivot_line->type != MD_LINE_TEXT)) {
  6246              line->type = MD_LINE_INDENTEDCODE;
  6247              line->indent -= ctx->code_indent_offset;
  6248              line->data = 0;
  6249              break;
  6250          }
  6251
  6252          /* Check for start of a new container block. */
  6253          if(line->indent < ctx->code_indent_offset  &&
  6254             md_is_container_mark(ctx, line->indent, off, &off, &container))
  6255          {
  6256              if(pivot_line->type == MD_LINE_TEXT  &&  n_parents == ctx->n_containers  &&
  6257                          (off >= ctx->size || ISNEWLINE(off))  &&  container.ch != _T('>'))
  6258              {
  6259                  /* Noop. List mark followed by a blank line cannot interrupt a paragraph. */
  6260              } else if(pivot_line->type == MD_LINE_TEXT  &&  n_parents == ctx->n_containers  &&
  6261                          ISANYOF2_(container.ch, _T('.'), _T(')'))  &&  container.start != 1)
  6262              {
  6263                  /* Noop. Ordered list cannot interrupt a paragraph unless the start index is 1. */
  6264              } else {
  6265                  total_indent += container.contents_indent - container.mark_indent;
  6266                  line->indent = md_line_indentation(ctx, total_indent, off, &off);
  6267                  total_indent += line->indent;
  6268
  6269                  line->beg = off;
  6270                  line->data = container.ch;
  6271
  6272                  /* Some of the following whitespace actually still belongs to the mark. */
  6273                  if(off >= ctx->size || ISNEWLINE(off)) {
  6274                      container.contents_indent++;
  6275                  } else if(line->indent <= ctx->code_indent_offset) {
  6276                      container.contents_indent += line->indent;
  6277                      line->indent = 0;
  6278                  } else {
  6279                      container.contents_indent += 1;
  6280                      line->indent--;
  6281                  }
  6282
  6283                  if(n_brothers + n_children == 0)
  6284                      pivot_line = &md_dummy_blank_line;
  6285
  6286                  if(n_children == 0)
  6287                      MD_CHECK(md_leave_child_containers(ctx, n_parents + n_brothers));
  6288
  6289                  n_children++;
  6290                  MD_CHECK(md_push_container(ctx, &container));
  6291                  continue;
  6292              }
  6293          }
  6294
  6295          /* Check whether we are table continuation. */
  6296          if(pivot_line->type == MD_LINE_TABLE  &&  n_parents == ctx->n_containers) {
  6297              line->type = MD_LINE_TABLE;
  6298              break;
  6299          }
  6300
  6301          /* Check for ATX header. */
  6302          if(line->indent < ctx->code_indent_offset  &&
  6303                  off < ctx->size  &&  CH(off) == _T('#'))
  6304          {
  6305              unsigned level;
  6306
  6307              if(md_is_atxheader_line(ctx, off, &line->beg, &off, &level)) {
  6308                  line->type = MD_LINE_ATXHEADER;
  6309                  line->data = level;
  6310                  break;
  6311              }
  6312          }
  6313
  6314          /* Check whether we are starting code fence. */
  6315          if(line->indent < ctx->code_indent_offset  &&
  6316                  off < ctx->size  &&  ISANYOF2(off, _T('`'), _T('~')))
  6317          {
  6318              if(md_is_opening_code_fence(ctx, off, &off)) {
  6319                  line->type = MD_LINE_FENCEDCODE;
  6320                  line->data = 1;
  6321                  line->enforce_new_block = TRUE;
  6322                  break;
  6323              }
  6324          }
  6325
  6326          /* Check for start of raw HTML block. */
  6327          if(off < ctx->size  &&  CH(off) == _T('<')
  6328              &&  !(ctx->parser.flags & MD_FLAG_NOHTMLBLOCKS))
  6329          {
  6330              ctx->html_block_type = md_is_html_block_start_condition(ctx, off);
  6331
  6332              /* HTML block type 7 cannot interrupt paragraph. */
  6333              if(ctx->html_block_type == 7  &&  pivot_line->type == MD_LINE_TEXT)
  6334                  ctx->html_block_type = 0;
  6335
  6336              if(ctx->html_block_type > 0) {
  6337                  /* The line itself also may immediately close the block. */
  6338                  if(md_is_html_block_end_condition(ctx, off, &off) == ctx->html_block_type) {
  6339                      /* Make sure this is the last line of the block. */
  6340                      ctx->html_block_type = 0;
  6341                  }
  6342
  6343                  line->enforce_new_block = TRUE;
  6344                  line->type = MD_LINE_HTML;
  6345                  break;
  6346              }
  6347          }
  6348
  6349          /* Check for table underline. */
  6350          if((ctx->parser.flags & MD_FLAG_TABLES)  &&  pivot_line->type == MD_LINE_TEXT
  6351              &&  off < ctx->size  &&  ISANYOF3(off, _T('|'), _T('-'), _T(':'))
  6352              &&  n_parents == ctx->n_containers)
  6353          {
  6354              unsigned col_count;
  6355
  6356              if(ctx->current_block != NULL  &&  ctx->current_block->n_lines == 1  &&
  6357                  md_is_table_underline(ctx, off, &off, &col_count))
  6358              {
  6359                  line->data = col_count;
  6360                  line->type = MD_LINE_TABLEUNDERLINE;
  6361                  break;
  6362              }
  6363          }
  6364
  6365          /* By default, we are normal text line. */
  6366          line->type = MD_LINE_TEXT;
  6367          if(pivot_line->type == MD_LINE_TEXT  &&  n_brothers + n_children == 0) {
  6368              /* Lazy continuation. */
  6369              n_parents = ctx->n_containers;
  6370          }
  6371
  6372          /* Check for task mark. */
  6373          if((ctx->parser.flags & MD_FLAG_TASKLISTS)  &&  n_brothers + n_children > 0  &&
  6374             ISANYOF_(ctx->containers[ctx->n_containers-1].ch, _T("-+*.)")))
  6375          {
  6376              OFF tmp = off;
  6377
  6378              while(tmp < ctx->size  &&  tmp < off + 3  &&  ISBLANK(tmp))
  6379                  tmp++;
  6380              if(tmp + 2 < ctx->size  &&  CH(tmp) == _T('[')  &&
  6381                 ISANYOF(tmp+1, _T("xX "))  &&  CH(tmp+2) == _T(']')  &&
  6382                 (tmp + 3 == ctx->size  ||  ISBLANK(tmp+3)  ||  ISNEWLINE(tmp+3)))
  6383              {
  6384                  MD_CONTAINER* task_container = (n_children > 0 ? &ctx->containers[ctx->n_containers-1] : &container);
  6385                  task_container->is_task = TRUE;
  6386                  task_container->task_mark_off = tmp + 1;
  6387                  off = tmp + 3;
  6388                  while(off < ctx->size  &&  ISWHITESPACE(off))
  6389                      off++;
  6390                  line->beg = off;
  6391              }
  6392          }
  6393
  6394          break;
  6395      }
  6396
  6397      /* Scan for end of the line. */
  6398      /* Optimization: Use some loop unrolling. */
  6399      while(off + 3 < ctx->size  &&  !ISNEWLINE(off+0)  &&  !ISNEWLINE(off+1)
  6400                                 &&  !ISNEWLINE(off+2)  &&  !ISNEWLINE(off+3))
  6401          off += 4;
  6402      while(off < ctx->size  &&  !ISNEWLINE(off))
  6403          off++;
  6404
  6405      /* Set end of the line. */
  6406      line->end = off;
  6407
  6408      /* But for ATX header, we should exclude the optional trailing mark. */
  6409      if(line->type == MD_LINE_ATXHEADER) {
  6410          OFF tmp = line->end;
  6411          while(tmp > line->beg && ISBLANK(tmp-1))
  6412              tmp--;
  6413          while(tmp > line->beg && CH(tmp-1) == _T('#'))
  6414              tmp--;
  6415          if(tmp == line->beg || ISBLANK(tmp-1) || (ctx->parser.flags & MD_FLAG_PERMISSIVEATXHEADERS))
  6416              line->end = tmp;
  6417      }
